import Foundation
@testable import RepoPromptApp
import XCTest

@MainActor
final class AgentComposerDraftRestorationTests: XCTestCase {
    func testCoalescedManualAndQueuedRecoveriesRestoreEachFragmentOnce() throws {
        let viewModel = makeViewModel()
        let tabID = UUID()
        let session = viewModel.session(for: tabID)
        viewModel.storeDraftText(for: tabID, "D")

        viewModel.restoreRejectedManualSubmissionComposerState(
            tabID: tabID,
            session: session,
            draftText: "B",
            images: [],
            taggedFiles: [],
            selectedWorkflow: nil,
            selectedWorkflowMutationGeneration: nil,
            message: "Failed start"
        )
        viewModel.restoreComposerDraft(
            tabID: tabID,
            text: "C",
            message: "Stopped queued work",
            strategy: .prependAlways
        )

        let finalEvent = try XCTUnwrap(viewModel.draftRestorationEvent)
        let operation = try XCTUnwrap(finalEvent.operation)
        XCTAssertEqual(viewModel.retrieveDraftText(for: tabID), "C\nB\nD")
        XCTAssertEqual(
            AgentComposerDraftRestorationReducer.apply(
                operation,
                to: "D",
                acknowledgedSequence: 0
            ),
            "C\nB\nD"
        )
    }

    func testConsumedRecoveryAndNewerTypingAreNotDuplicated() throws {
        let viewModel = makeViewModel()
        let tabID = UUID()
        viewModel.storeDraftText(for: tabID, "D")
        viewModel.restoreComposerDraft(
            tabID: tabID,
            text: "B",
            message: "Failed start",
            strategy: .prependAlways
        )
        let firstOperation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        let firstEditorText = AgentComposerDraftRestorationReducer.apply(
            firstOperation,
            to: "D",
            acknowledgedSequence: 0
        )
        XCTAssertEqual(firstEditorText, "B\nD")

        let editedText = firstEditorText + "\nnew typing"
        viewModel.storeDraftText(
            for: tabID,
            editedText,
            acknowledgingThrough: firstOperation.fragments.last?.sequence ?? 0
        )
        viewModel.restoreComposerDraft(
            tabID: tabID,
            text: "C",
            message: "Stopped queued work",
            strategy: .prependAlways
        )
        let finalOperation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        XCTAssertEqual(
            AgentComposerDraftRestorationReducer.apply(
                finalOperation,
                to: editedText,
                acknowledgedSequence: firstOperation.fragments.last?.sequence ?? 0
            ),
            "C\nB\nD\nnew typing"
        )
    }

    func testSkippedIntermediateRecoveryStillAppliesOnlyMissingFragments() throws {
        let viewModel = makeViewModel()
        let tabID = UUID()
        viewModel.storeDraftText(for: tabID, "D")
        viewModel.restoreComposerDraft(tabID: tabID, text: "A", message: "", strategy: .prependAlways)
        let firstOperation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        let firstEditorText = AgentComposerDraftRestorationReducer.apply(
            firstOperation,
            to: "D",
            acknowledgedSequence: 0
        )
        viewModel.restoreComposerDraft(tabID: tabID, text: "B", message: "", strategy: .prependAlways)
        viewModel.restoreComposerDraft(tabID: tabID, text: "C", message: "", strategy: .prependAlways)

        let finalOperation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        XCTAssertEqual(
            AgentComposerDraftRestorationReducer.apply(
                finalOperation,
                to: firstEditorText,
                acknowledgedSequence: firstOperation.fragments.last?.sequence ?? 0
            ),
            "C\nB\nA\nD"
        )
    }

    func testInterleavedTabsRetainEachTabsUnconsumedFragments() throws {
        let viewModel = makeViewModel()
        let tabID = UUID()
        let otherTabID = UUID()
        viewModel.storeDraftText(for: tabID, "D")

        viewModel.restoreComposerDraft(tabID: tabID, text: "A", message: "", strategy: .prependAlways)
        viewModel.restoreComposerDraft(tabID: otherTabID, text: "X", message: "", strategy: .prependAlways)
        viewModel.restoreComposerDraft(tabID: tabID, text: "B", message: "", strategy: .prependAlways)

        let operation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        XCTAssertEqual(operation.fragments.map(\.text), ["A", "B"])
        let editorText = AgentComposerDraftRestorationReducer.apply(
            operation,
            to: "D",
            acknowledgedSequence: 0
        )
        XCTAssertEqual(editorText, "B\nA\nD")
        viewModel.storeDraftText(
            for: tabID,
            editorText,
            acknowledgingThrough: operation.fragments.last?.sequence ?? 0
        )
        XCTAssertEqual(viewModel.retrieveDraftText(for: tabID), "B\nA\nD")
        XCTAssertTrue(viewModel.draftRestorationLedger.tabs[tabID]?.pendingFragments.isEmpty == true)
        XCTAssertEqual(viewModel.draftRestorationLedger.tabs[otherTabID]?.pendingFragments.map(\.text), ["X"])
    }

    func testStaleEditorStorePreservesRecoveryPendingAtTabSwitch() {
        let viewModel = makeViewModel()
        let tabID = UUID()
        viewModel.storeDraftText(for: tabID, "D")
        viewModel.restoreComposerDraft(tabID: tabID, text: "A", message: "", strategy: .prependAlways)

        // The old editor value is stored as the tab changes before it sees A.
        viewModel.storeDraftText(for: tabID, "D", acknowledgingThrough: 0)
        XCTAssertEqual(viewModel.retrieveDraftText(for: tabID), "A\nD")
        let snapshot = viewModel.loadDraftSnapshotForComposer(for: tabID)
        XCTAssertEqual(snapshot.text, "A\nD")
        XCTAssertTrue(viewModel.draftRestorationLedger.tabs[tabID]?.pendingFragments.isEmpty == true)
    }

    func testLoadedSnapshotAndDeletionDoNotResurrectAcknowledgedRecovery() throws {
        let viewModel = makeViewModel()
        let tabID = UUID()
        viewModel.restoreComposerDraft(tabID: tabID, text: "A", message: "", strategy: .prependAlways)
        let oldOperation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        let snapshot = viewModel.loadDraftSnapshotForComposer(for: tabID)
        XCTAssertEqual(snapshot.text, "A")
        XCTAssertTrue(viewModel.draftRestorationLedger.tabs[tabID]?.pendingFragments.isEmpty == true)

        viewModel.storeDraftText(for: tabID, "", acknowledgingThrough: snapshot.restorationSequence)
        XCTAssertEqual(
            AgentComposerDraftRestorationReducer.apply(
                oldOperation,
                to: "",
                acknowledgedSequence: snapshot.restorationSequence
            ),
            ""
        )
        viewModel.restoreComposerDraft(tabID: tabID, text: "B", message: "", strategy: .prependAlways)
        viewModel.restoreComposerDraft(tabID: tabID, text: "C", message: "", strategy: .prependAlways)

        let operation = try XCTUnwrap(viewModel.draftRestorationEvent?.operation)
        XCTAssertEqual(operation.fragments.map(\.text), ["B", "C"])
        let editorText = AgentComposerDraftRestorationReducer.apply(
            operation,
            to: "",
            acknowledgedSequence: snapshot.restorationSequence
        )
        XCTAssertEqual(editorText, "C\nB")
        viewModel.storeDraftText(
            for: tabID,
            editorText,
            acknowledgingThrough: operation.fragments.last?.sequence ?? 0
        )
        XCTAssertEqual(viewModel.retrieveDraftText(for: tabID), "C\nB")
        XCTAssertTrue(viewModel.draftRestorationLedger.tabs[tabID]?.pendingFragments.isEmpty == true)
    }

    private func makeViewModel() -> AgentModeViewModel {
        AgentModeViewModel(
            codexControllerFactory: { _, _, _, _, _, _ in
                preconditionFailure("Draft restoration tests must not start Codex")
            },
            headlessProviderFactory: { _, _ in
                UnsupportedHeadlessAgentProvider(reason: "draft restoration test")
            }
        )
    }
}

import Darwin
import Foundation
@testable import RepoPromptMCPCore
import XCTest

final class BootstrapSocketMCPTransportIngressTests: XCTestCase {
    func testWithheldConsumerReportsOverflowInsteadOfDroppingTerminalResponse() async throws {
        let pair = try makeSocketPair()
        defer { Darwin.close(pair[1]) }
        let transport = try BootstrapSocketMCPTransport(connectedFD: pair[0])
        try await transport.connect()
        let frames = numberedFrames(count: 1025)
        try writeFrames(frames, to: pair[1])
        XCTAssertEqual(shutdown(pair[1], SHUT_WR), 0)
        try waitForPeerShutdown(pair[1])

        let stream = await transport.receive()
        var observed: [Data] = []
        var terminalError: Error?
        do {
            for try await frame in stream {
                observed.append(frame)
            }
        } catch { terminalError = error }
        XCTAssertEqual(observed, Array(frames.prefix(1024)))
        XCTAssertEqual(
            terminalError as? BootstrapSocketReceiveBufferOverflowError,
            BootstrapSocketReceiveBufferOverflowError(capacity: 1024)
        )
        await transport.disconnect()
    }

    func testAtCapacityPreservesEveryFrameBeforeCleanEOF() async throws {
        let pair = try makeSocketPair()
        defer { Darwin.close(pair[1]) }
        let transport = try BootstrapSocketMCPTransport(connectedFD: pair[0])
        try await transport.connect()
        let frames = numberedFrames(count: 1024)
        try writeFrames(frames, to: pair[1])
        XCTAssertEqual(shutdown(pair[1], SHUT_WR), 0)
        try waitForPeerShutdown(pair[1])
        var observed: [Data] = []
        for try await frame in await transport.receive() {
            observed.append(frame)
        }
        XCTAssertEqual(observed, frames)
        await transport.disconnect()
    }

    func testInjectedOverflowUsesConfiguredCapacityAndIgnoresStaleToken() async throws {
        let pair = try makeSocketPair()
        defer { Darwin.close(pair[1]) }
        let transport = try BootstrapSocketMCPTransport(connectedFD: pair[0], receiveBufferCapacity: 3)
        await transport.debugHoldReaderTerminalCallback()
        await transport.debugHoldReaderCancellationCallback()
        try await transport.connect()

        // A stale identity must leave ingress and the adopted connection live.
        await transport.debugDeliverReceiveOverflow(token: 2)
        try await transport.connect()
        let frames = numberedFrames(count: 3)
        try writeFrames(frames, to: pair[1])
        XCTAssertEqual(shutdown(pair[1], SHUT_WR), 0)
        await transport.debugWaitForHeldReaderTerminalCallback()
        let pending = await transport.debugIngressTeardownCounts()
        XCTAssertEqual(pending.finalized, 0)
        XCTAssertEqual(pending.closed, 0)

        // Exactly capacity frames means no real overflow error can mask the
        // injected callback's configured-capacity diagnostic.
        await transport.debugDeliverReceiveOverflow(token: 1)
        var observed: [Data] = []
        var terminalError: Error?
        do {
            for try await frame in await transport.receive() {
                observed.append(frame)
            }
        } catch { terminalError = error }
        XCTAssertEqual(observed, frames)
        XCTAssertEqual(
            terminalError as? BootstrapSocketReceiveBufferOverflowError,
            BootstrapSocketReceiveBufferOverflowError(capacity: 3)
        )
        await transport.debugDeliverReaderCancellation(token: 1)
        await transport.debugDeliverReceiveOverflow(token: 2)
        let settled = await transport.debugIngressTeardownCounts()
        XCTAssertEqual(settled.finalized, 1)
        XCTAssertEqual(settled.closed, 1)
        try waitForPeerShutdown(pair[1])
        await transport.debugReleaseReaderTerminalCallbacks()
        await transport.debugReleaseReaderCancellationCallbacks()
        await transport.disconnect()
    }

    func testEOFFirstKeepsOverflowAndSettlesReaderExactlyOnce() async throws {
        try await assertDelayedTeardown(overflowFirst: false)
    }

    func testOverflowFirstIgnoresDelayedEOFAndSettlesReaderExactlyOnce() async throws {
        try await assertDelayedTeardown(overflowFirst: true)
    }

    private func assertDelayedTeardown(overflowFirst: Bool) async throws {
        let pair = try makeSocketPair()
        defer { Darwin.close(pair[1]) }
        let transport = try BootstrapSocketMCPTransport(connectedFD: pair[0], receiveBufferCapacity: 2)
        await transport.debugHoldReaderTerminalCallback()
        await transport.debugHoldReceiveOverflowCallback()
        await transport.debugHoldReaderCancellationCallback()
        try await transport.connect()

        // Wrong generation must not close a live socket, even with the same fd.
        await transport.debugDeliverReceiveOverflow(token: 2)
        await transport.debugDeliverReaderEOF(token: 2)
        let frames = numberedFrames(count: 5)
        try writeFrames(frames, to: pair[1])
        XCTAssertEqual(shutdown(pair[1], SHUT_WR), 0)
        // This observes the real EOF callback after all five numbered reader
        // callbacks. Overflow and actor teardown remain held independently.
        await transport.debugWaitForHeldReaderTerminalCallback()
        if overflowFirst {
            await transport.debugDeliverReceiveOverflow(token: 1)
        } else {
            await transport.debugDeliverReaderEOF(token: 1)
        }
        var observed: [Data] = []
        var terminalError: Error?
        do {
            for try await frame in await transport.receive() {
                observed.append(frame)
            }
        } catch { terminalError = error }
        XCTAssertEqual(observed, Array(frames.prefix(2)), "No frame after the gap may enter the stream")
        XCTAssertEqual(
            terminalError as? BootstrapSocketReceiveBufferOverflowError,
            BootstrapSocketReceiveBufferOverflowError(capacity: 2)
        )
        do {
            try await transport.send(Data("after overflow".utf8))
            XCTFail("A failed transport must reject later sends")
        } catch {}
        do {
            try await transport.connect()
            XCTFail("An adopted socket cannot be reconnected after overflow")
        } catch {}

        let pending = await transport.debugIngressTeardownCounts()
        XCTAssertEqual(pending.finalized, 0)
        XCTAssertEqual(pending.closed, 0, "Only the matching cancellation finalizer closes the descriptor")
        await transport.debugDeliverReaderCancellation(token: 2)
        await transport.debugDeliverReaderCancellation(token: 1)
        await transport.debugDeliverReaderCancellation(token: 1)
        await transport.debugDeliverReaderEOF(token: 1)
        await transport.debugDeliverReceiveOverflow(token: 1)
        await transport.disconnect()
        let settled = await transport.debugIngressTeardownCounts()
        XCTAssertEqual(settled.finalized, 1)
        XCTAssertEqual(settled.closed, 1)
        // Cancellation owns the physical close. Peer EOF is observable only
        // after that held, matching-identity finalizer has closed the descriptor.
        try waitForPeerShutdown(pair[1])
        XCTAssertEqual(settled.staleTerminal, 2)
        XCTAssertEqual(settled.staleCancellation, 2)
        await transport.debugReleaseReaderTerminalCallbacks()
        await transport.debugReleaseReceiveOverflowCallbacks()
        await transport.debugReleaseReaderCancellationCallbacks()
    }

    private func numberedFrames(count: Int) -> [Data] {
        (1 ... count).map { Data("{\"jsonrpc\":\"2.0\",\"id\":\($0),\"result\":\($0)}".utf8) }
    }

    private func makeSocketPair() throws -> [Int32] {
        var descriptors: [Int32] = [-1, -1]
        guard socketpair(AF_UNIX, SOCK_STREAM, 0, &descriptors) == 0 else {
            throw POSIXError(.init(rawValue: errno) ?? .EIO)
        }
        return descriptors
    }

    private func writeFrames(_ frames: [Data], to descriptor: Int32) throws {
        var data = Data()
        for frame in frames {
            data.append(frame)
            data.append(0x0A)
        }
        try data.withUnsafeBytes { bytes in
            var offset = 0
            while offset < bytes.count {
                let result = Darwin.write(descriptor, bytes.baseAddress!.advanced(by: offset), bytes.count - offset)
                guard result > 0 else { throw POSIXError(.init(rawValue: errno) ?? .EIO) }
                offset += result
            }
        }
    }

    /// EOF on the peer proves the transport has read and settled ingress before
    /// the consumer starts. The bounded poll is a failure deadline, not a sleep.
    private func waitForPeerShutdown(_ descriptor: Int32) throws {
        var descriptorPoll = pollfd(fd: descriptor, events: Int16(POLLIN), revents: 0)
        guard poll(&descriptorPoll, 1, 5000) > 0 else {
            XCTFail("Transport did not shut down after inbound EOF")
            throw POSIXError(.ETIMEDOUT)
        }
        var byte: UInt8 = 0
        XCTAssertEqual(Darwin.read(descriptor, &byte, 1), 0)
    }
}

import Foundation
import RepoPromptTestSupport
import XCTest

/// Cross-window oversight carries another session's transcript text, display names, and delivered
/// message bodies through this surface. A single `debugLog("send \(message)")` added later would
/// republish that content, unredacted, into a log file that the sanitizer never sees and that no
/// response-shape test inspects.
///
/// The shipped surface emits none of these facilities, so this guard pins that property rather than
/// trying to prove that some future log line happens to be redacted. If a diagnostic is genuinely
/// needed here, add it deliberately and extend this test with the exact allowed call and the reason
/// its arguments cannot carry overseen content.
///
/// One facility is deliberately allowed: the debug-only, opt-in `WorkspaceRestorePerfLog` shared with
/// window/workspace restore. Its oversight call sites are compiled behind `#if DEBUG` and pass only
/// enum-like outcome labels, counts, window IDs, and `shortID` identifier prefixes — never a
/// transcript item, a session or workspace name, a delivered message, a worktree/backup path, or a
/// full session UUID. It is not listed above because a redacted structural counter is exactly the
/// diagnostic this surface needs; a new call site must keep those argument rules.
final class AgentSessionLinkDiagnosticsRedactionGuardTests: XCTestCase {
    /// Every logging facility used anywhere in this repository.
    ///
    /// Matched with a leading non-identifier boundary so `footprint`, `blueprint`, and
    /// `fingerprintLog` do not register as hits.
    private static let forbiddenCalls = [
        "print",
        "debugPrint",
        "dump",
        "NSLog",
        "os_log",
        "Logger",
        "debugLog",
        "steeringDebugLog",
        "logCodex",
        "logCodexDebug",
        "logHandoffDebug",
        "mcpServerViewModelDebugLog",
        "mcpRoutingInternalDebugLog"
    ]

    /// Directory whose entire contents are session-link owned, so files added later are guarded
    /// automatically instead of silently escaping this test.
    private static let guardedDirectory = "Sources/RepoPrompt/Features/AgentMode/Runtime/SessionLinks"

    /// Session-link files that live outside the guarded directory.
    private static let guardedFiles = [
        "Sources/RepoPromptDomainRuntime/DomainAgentSessionLinkAuthority.swift",
        "Sources/RepoPromptDomainRuntime/DomainAgentSessionLinkModels.swift",
        "Sources/RepoPromptDomainRuntime/DomainAgentSessionOperationAuthorizer.swift",
        "Sources/RepoPrompt/Infrastructure/MCP/Agent/AgentSessionLinkMCPToolService.swift",
        "Sources/RepoPrompt/Infrastructure/MCP/Agent/AgentSessionTargetOperationGuard.swift",
        "Sources/RepoPrompt/Infrastructure/AI/Prompts/AgentSessionLinkPrompts.swift",
        "Sources/RepoPrompt/App/WindowStatesManager+AgentSessionLinks.swift",
        "Sources/RepoPrompt/Features/AgentMode/ViewModels/UI/AgentMonitorPillModels.swift",
        "Sources/RepoPrompt/Features/AgentMode/Views/Components/AgentMonitorPill.swift"
    ]

    func testMonitoringSurfaceEmitsNoLoggingThatCouldCarryMonitoredContent() throws {
        let root = try RepoRoot.url()
        let sources = try guardedSourceURLs(root: root)
        XCTAssertGreaterThan(sources.count, 12, "guard list resolved to too few files; paths likely moved")

        var violations: [String] = []
        for url in sources {
            let code = try Self.strippingComments(String(contentsOf: url, encoding: .utf8))
            for call in Self.forbiddenCalls where Self.containsCall(call, in: code) {
                violations.append("\(RepoRoot.relativePath(for: url, relativeTo: root)) calls \(call)(")
            }
        }
        XCTAssertEqual(
            violations,
            [],
            """
            Cross-window oversight source emitted logging. Overseen transcript text, display names, \
            and delivered message bodies pass through here, so any log argument must be proven \
            content-free before this guard is relaxed.
            """
        )
    }

    /// The guarded directory must actually be the session-link implementation, so a rename that
    /// empties it fails loudly instead of turning the whole guard into a no-op.
    func testGuardedPathsAllExist() throws {
        let root = try RepoRoot.url()
        var isDirectory: ObjCBool = false
        let directory = root.appendingPathComponent(Self.guardedDirectory, isDirectory: true)
        XCTAssertTrue(
            FileManager.default.fileExists(atPath: directory.path, isDirectory: &isDirectory)
                && isDirectory.boolValue,
            "missing guarded directory \(Self.guardedDirectory)"
        )
        for path in Self.guardedFiles {
            XCTAssertTrue(
                FileManager.default.fileExists(atPath: root.appendingPathComponent(path).path),
                "missing guarded file \(path)"
            )
        }
    }

    // MARK: - Helpers

    private func guardedSourceURLs(root: URL) throws -> [URL] {
        let directory = root.appendingPathComponent(Self.guardedDirectory, isDirectory: true)
        let contents = try FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: nil
        )
        let inDirectory = contents.filter { $0.pathExtension == "swift" }
        return inDirectory + Self.guardedFiles.map { root.appendingPathComponent($0) }
    }

    /// Removes whole-line `//` comments so prose such as "never print the message body" cannot trip
    /// the scan. Trailing comments are deliberately left in place: keeping the scan conservative is
    /// preferable to mis-parsing a `//` inside a string literal.
    private static func strippingComments(_ source: String) -> String {
        source
            .components(separatedBy: .newlines)
            .filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//") }
            .joined(separator: "\n")
    }

    private static func containsCall(_ name: String, in code: String) -> Bool {
        let pattern = "(?<![A-Za-z0-9_.])\(NSRegularExpression.escapedPattern(for: name))\\s*\\("
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return false }
        let range = NSRange(code.startIndex..., in: code)
        return regex.firstMatch(in: code, range: range) != nil
    }
}

import Foundation
import RepoPromptSecureStorage

/// Owns only the dedicated Decisions credential. Selection and durable feature intent live elsewhere.
actor OpenAIDecisionsRouterCredentialService: DecisionServiceConfigurationController {
    typealias Decide = @Sendable (OpenAIDecisionsWireRequest, String) async throws -> OpenAIDecisionsWireResponse
    enum ValidationResult: Equatable {
        case saved(generation: UInt64)
        case missingKey
        case superseded
        case failed(String)
    }

    static let pinnedModel = OpenAIDecisionsRoutingResponseInterpreter.pinnedModel
    static let routingPolicyVersion = "openai-decisions-gpt-6-luna-rpce-v2"
    /// Fixed benign billable access probe; never populated from a user task.
    static let validationRequest = OpenAIDecisionsWireRequest(
        model: pinnedModel, input: "Choose the label for the word apple.",
        questions: [.init(name: "credential_access", instructions: "Choose the matching category.", choices: [
            .init(value: "fruit", description: "An edible fruit."),
            .init(value: "vehicle", description: "A means of transportation.")
        ])]
    )

    private let secureKeys: SecureKeysService
    private let decide: Decide
    private var generation: UInt64 = 0
    private var stable: DecisionReadiness = .needsConfiguration(generation: 0, reason: "Validate a Decisions OpenAI API key first.")
    private var activeID: UUID?
    private var activeTask: Task<OpenAIDecisionsWireResponse, Error>?
    private var startupAttemptedGeneration: UInt64?
    private var observers: [UUID: AsyncStream<DecisionReadiness>.Continuation] = [:]

    init(secureKeys: SecureKeysService = SecureKeysService(), decide: @escaping Decide = { request, key in
        try await OpenAIDecisionsRoutingClient().decide(request, apiKey: key)
    }) {
        self.secureKeys = secureKeys
        self.decide = decide
    }

    func readinessSnapshot() -> DecisionReadiness {
        activeID == nil ? stable : .validating(generation: generation)
    }

    func readinessUpdates() -> AsyncStream<DecisionReadiness> {
        let id = UUID()
        return AsyncStream { continuation in
            observers[id] = continuation
            continuation.yield(readinessSnapshot())
            continuation.onTermination = { [weak self] _ in Task { await self?.removeObserver(id) } }
        }
    }

    func validateAndSave(_ candidate: String, operationID: UUID) async -> ValidationResult {
        let key = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return .missingKey }
        begin(operationID)
        defer { finish(operationID) }
        do {
            try await probe(key, operationID: operationID)
            guard activeID == operationID, !Task.isCancelled else { return .superseded }
            do {
                // Synchronous durable commit: no cancellation check after a confirmed save.
                try secureKeys.saveAPIKey(key, for: .openAIDecisionsRouterAPIKey, accessMode: .interactive)
            } catch {
                advanceReady(false)
                startupAttemptedGeneration = generation // Explicit revalidation owns recovery after an ambiguous mutation.
                return .failed("Secure storage may have changed. Revalidate the stored Decisions key.")
            }
            advanceReady(true)
            startupAttemptedGeneration = generation
            return .saved(generation: generation)
        } catch {
            guard activeID == operationID, !Task.isCancelled else { return .superseded }
            if Self.isCancellation(error) { return .superseded }
            // Candidate failures leave the stable credential untouched, never restore an overlay.
            return .failed(Self.message(error))
        }
    }

    func validateStoredKey(operationID: UUID, accessMode: KeychainAccessMode = .interactive) async -> ValidationResult {
        begin(operationID)
        defer { finish(operationID) }
        do {
            let key = try await secureKeys.getAPIKey(for: .openAIDecisionsRouterAPIKey, accessMode: accessMode)
            guard activeID == operationID, !Task.isCancelled else { return .superseded }
            guard let key, !key.isEmpty else {
                advanceReady(false)
                return .missingKey
            }
            try await probe(key, operationID: operationID)
            guard activeID == operationID, !Task.isCancelled else { return .superseded }
            advanceReady(true)
            startupAttemptedGeneration = generation
            return .saved(generation: generation)
        } catch {
            guard activeID == operationID, !Task.isCancelled else { return .superseded }
            if Self.isCancellation(error) { return .superseded }
            if error as? OpenAIDecisionsRoutingClientError == .policyUnavailable {
                stable = .policyUnavailable(generation: generation, reason: Self.message(error))
            } else {
                stable = .temporarilyUnavailable(generation: generation, reason: Self.message(error))
            }
            return .failed(Self.message(error))
        }
    }

    func delete(operationID: UUID) throws {
        begin(operationID)
        defer { finish(operationID) }
        do {
            try secureKeys.deleteAPIKey(for: .openAIDecisionsRouterAPIKey, accessMode: .interactive)
            advanceReady(false)
            startupAttemptedGeneration = nil
        } catch {
            // These concrete Keychain delete errors occur before mutation. Unknown backends/errors
            // provide no such guarantee and must fence readiness rather than claim the old key survived.
            switch error as? KeychainService.KeychainError {
            case .interactionNotAllowed, .userInteractionCancelled, .authenticationFailed: break
            default:
                advanceReady(false)
                startupAttemptedGeneration = generation
            }
            throw error
        }
    }

    func judgeForRouting(_ request: OpenAIDecisionsWireRequest) async throws -> OpenAIDecisionsWireResponse {
        guard activeID == nil, stable.isReady else { throw OpenAIDecisionsRoutingClientError.policyUnavailable }
        let captured = generation
        let key: String?
        do {
            key = try await secureKeys.getAPIKey(for: .openAIDecisionsRouterAPIKey, accessMode: .nonInteractive(reason: .backgroundAvailabilityCheck))
        } catch {
            if generation == captured, activeID == nil {
                stable = .temporarilyUnavailable(generation: generation, reason: "Secure storage access is unavailable.")
                publish()
            }
            throw OpenAIDecisionsRoutingClientError.policyUnavailable
        }
        guard generation == captured, activeID == nil, stable.isReady else { throw OpenAIDecisionsRoutingClientError.policyUnavailable }
        guard let key, !key.isEmpty else {
            advanceReady(false)
            throw OpenAIDecisionsRoutingClientError.policyUnavailable
        }
        // Remote errors, including ambiguous 401, cannot invalidate or delete a credential.
        let response = try await decide(request, key)
        guard generation == captured, activeID == nil, stable.isReady else { throw OpenAIDecisionsRoutingClientError.policyUnavailable }
        return response
    }

    func bootstrapStoredConfigurationIfNeeded() async {
        guard activeID == nil, startupAttemptedGeneration != generation else { return }
        startupAttemptedGeneration = generation
        let result = await validateStoredKey(operationID: UUID(), accessMode: .nonInteractive(reason: .backgroundAvailabilityCheck))
        guard result != .superseded else { return }
        // Missing-key validation can fence the generation too; do not rebill at that new state.
        startupAttemptedGeneration = generation
    }

    func cancelValidation() {
        activeTask?.cancel()
        activeTask = nil
        activeID = nil
        publish()
    }

    func cancelAndAdvanceGeneration() {
        cancelValidation()
        advanceReady(false)
        startupAttemptedGeneration = nil
    }

    func perform(_ action: DecisionServiceSettingsAction) async -> DecisionServiceSettingsActionResult {
        let result: ValidationResult
        switch action {
        case let .validateAndSaveSecret(secret): result = await validateAndSave(secret, operationID: UUID())
        case .revalidateStoredSecret: result = await validateStoredKey(operationID: UUID())
        case .removeStoredSecret:
            do { try delete(operationID: UUID())
                return .succeeded("Stored Decisions key removed.")
            } catch { return .failed("The stored Decisions key could not be removed.") }
        }
        switch result {
        case .saved: return .succeeded("Decisions access verified at this moment. Routing is ready.")
        case .missingKey: return .missingSecret("Enter an API key for Decisions by OpenAI.")
        case .superseded: return .superseded("Validation was cancelled or superseded.")
        case let .failed(message): return .failed(message)
        }
    }

    private func probe(_ key: String, operationID: UUID) async throws {
        let decide = decide
        let task = Task {
            try await OpenAIDecisionsCredentialFirstResult().run { try await decide(Self.validationRequest, key) }
        }
        activeTask = task
        let response = try await withTaskCancellationHandler { try await task.value } onCancel: { task.cancel() }
        guard activeID == operationID, !Task.isCancelled else { throw CancellationError() }
        let interpreted = try OpenAIDecisionsRoutingResponseInterpreter().interpret(response, expectedQuestionName: "credential_access", submittedChoices: ["fruit", "vehicle"])
        guard case .choice = interpreted else { throw OpenAIDecisionsRoutingClientError.invalidResponse }
    }

    private func begin(_ id: UUID) {
        activeTask?.cancel()
        activeTask = nil
        activeID = id
        publish()
    }

    private func finish(_ id: UUID) {
        guard activeID == id else { return }
        activeTask = nil
        activeID = nil
        publish()
    }

    private func advanceReady(_ ready: Bool) {
        generation &+= 1
        stable = ready ? .ready(generation: generation, policyVersion: Self.routingPolicyVersion) : .needsConfiguration(generation: generation, reason: "Validate a Decisions OpenAI API key first.")
        publish()
    }

    private func publish() {
        for observer in observers.values {
            observer.yield(readinessSnapshot())
        }
    }

    private func removeObserver(_ id: UUID) {
        observers.removeValue(forKey: id)
    }

    private static func isCancellation(_ error: Error) -> Bool {
        error is CancellationError || error as? OpenAIDecisionsRoutingClientError == .cancelled
    }

    private static func message(_ error: Error) -> String {
        if error as? OpenAIDecisionsRoutingClientError == .policyUnavailable { return "Decisions access is unavailable for this project or account." }
        if error is KeychainService.KeychainError { return "Secure storage access is unavailable." }
        return "Decisions validation is temporarily unavailable or returned an invalid response."
    }
}

/// Settles validation promptly even if an injected operation ignores cancellation. Only the actor
/// can commit storage; this detached response owner can never save or publish readiness.
private final class OpenAIDecisionsCredentialFirstResult: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<OpenAIDecisionsWireResponse, Error>?
    private var result: Result<OpenAIDecisionsWireResponse, Error>?
    private var task: Task<Void, Never>?
    func run(_ operation: @escaping @Sendable () async throws -> OpenAIDecisionsWireResponse) async throws -> OpenAIDecisionsWireResponse {
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                lock.lock()
                if let result { lock.unlock()
                    continuation.resume(with: result)
                    return
                }
                self.continuation = continuation
                lock.unlock()
                let task = Task { do { try await self.settle(.success(operation())) } catch { self.settle(.failure(error)) } }
                lock.lock()
                if result != nil { lock.unlock()
                    task.cancel()
                } else { self.task = task
                    lock.unlock()
                }
            }
        } onCancel: { self.settle(.failure(CancellationError())) }
    }

    private func settle(_ result: Result<OpenAIDecisionsWireResponse, Error>) {
        lock.lock()
        guard self.result == nil else { lock.unlock()
            return
        }
        self.result = result
        let continuation = continuation
        self.continuation = nil
        let task = task
        self.task = nil
        lock.unlock()
        task?.cancel()
        continuation?.resume(with: result)
    }
}

import Foundation
@testable import RepoPromptDomainRuntime
import XCTest

final class DomainAgentSessionLaneAuthorizationTests: XCTestCase {
    func testCreationRequiresAnAgentCallerWithALinkInEitherDirection() {
        let caller = DomainAgentSessionCallerIdentity.agentSession(UUID())
        let inboundOnly = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorCreateLane,
            caller: caller,
            hasActiveOutboundLink: false,
            hasActiveInboundLink: true
        )
        XCTAssertEqual(inboundOnly.basis, .observerGrantSet)
        let outboundOnly = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorCreateLane,
            caller: caller,
            hasActiveOutboundLink: true
        )
        XCTAssertEqual(outboundOnly.basis, .observerGrantSet)
        let unlinked = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorCreateLane,
            caller: caller,
            hasActiveOutboundLink: false
        )
        XCTAssertEqual(unlinked.denial, .noActiveLink)
        let listInboundOnly = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorList,
            caller: caller,
            hasActiveOutboundLink: false,
            hasActiveInboundLink: true
        )
        XCTAssertEqual(listInboundOnly.denial, .noActiveOutboundLink)
        let administrative = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorCreateLane,
            caller: .administrativePrincipal,
            hasActiveOutboundLink: true
        )
        XCTAssertEqual(administrative.denial, .monitorRequiresAgentCaller)
    }

    func testLaneOperationTableRows() {
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorCreateLane.family, .monitor)
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorCreateLane.isObserverScoped)
        XCTAssertNil(DomainAgentSessionTargetOperation.monitorCreateLane.requiredMonitorCapability)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorCreateLane.mutatesTarget)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorRetireLane.family, .monitor)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorRetireLane.isObserverScoped)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorRetireLane.requiredMonitorCapability, .manage)
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorRetireLane.mutatesTarget)
    }
}

