    private func makeAskUser(id: UUID = UUID(), options: [String] = ["Yes", "No"]) -> AgentAskUserPendingState {
        AgentAskUserPendingState(interaction: AgentAskUserInteraction(
            id: id,
            questions: [AgentAskUserQuestion(
                id: "q1",
                question: "Proceed?",
                options: options.map { AgentAskUserOption(label: $0) }
            )]
        ))
    }

    func testNoPendingInteractionYieldsNil() {
        XCTAssertNil(AgentPendingInteractionDescriptor.make(from: AgentTabSession(tabID: UUID())))
    }

    func testPriorityMirrorsTheCardChain() {
        let session = AgentTabSession(tabID: UUID())
        let approvalID = UUID()
        session.pendingAskUser = makeAskUser()
        session.pendingApproval = makeApproval(id: approvalID)

        let descriptor = AgentPendingInteractionDescriptor.make(from: session)
        XCTAssertEqual(descriptor?.kind, .approval, "An approval card outranks an ask_user card")
        XCTAssertEqual(descriptor?.id, approvalID)

        session.pendingApproval = nil
        XCTAssertEqual(AgentPendingInteractionDescriptor.make(from: session)?.kind, .askUser)
    }

    func testApprovalCarriesExactCommand() throws {
        let session = AgentTabSession(tabID: UUID())
        session.pendingApproval = makeApproval(command: "swift test ")
        let descriptor = try XCTUnwrap(AgentPendingInteractionDescriptor.make(from: session))
        XCTAssertEqual(descriptor.command, "swift test ", "Commands are never trimmed or rewritten")
        XCTAssertEqual(descriptor.approvalKind, .commandExecution)
    }

    func testAskUserSingleQuestionShape() throws {
        let session = AgentTabSession(tabID: UUID())
        session.pendingAskUser = makeAskUser(options: ["A", "B"])
        let descriptor = try XCTUnwrap(AgentPendingInteractionDescriptor.make(from: session))
        XCTAssertEqual(descriptor.questionID, "q1")
        XCTAssertEqual(descriptor.optionLabels, ["A", "B"])
        XCTAssertEqual(descriptor.questionCount, 1)
        XCTAssertEqual(descriptor.detail, "Proceed?")
    }

    func testFingerprintIsStableAndContentSensitive() {
        let id = UUID()
        let first = AgentPendingInteractionDescriptor(id: id, kind: .approval, title: "t", detail: "ls", command: "ls")
        let same = AgentPendingInteractionDescriptor(id: id, kind: .approval, title: "t", detail: "ls", command: "ls")
        let changedCommand = AgentPendingInteractionDescriptor(id: id, kind: .approval, title: "t", detail: "ls", command: "ls -a")
        let changedOptions = AgentPendingInteractionDescriptor(id: id, kind: .askUser, title: "t", detail: "q", optionLabels: ["A"])
        let reorderedOptions = AgentPendingInteractionDescriptor(id: id, kind: .askUser, title: "t", detail: "q", optionLabels: ["B"])

        XCTAssertEqual(first.fingerprint, same.fingerprint)
        XCTAssertEqual(first.fingerprint.count, 32)
        XCTAssertNotEqual(first.fingerprint, changedCommand.fingerprint)
        XCTAssertNotEqual(changedOptions.fingerprint, reorderedOptions.fingerprint)
    }
}

import Foundation
@testable import RepoPromptDomainRuntime
import XCTest

/// The common execution-time matrix that keeps a disclosed sibling UUID from bypassing monitor
/// capabilities through the existing `agent_run` / `agent_manage` control surfaces.
final class DomainAgentSessionOperationAuthorizerTests: XCTestCase {
    private let callerSessionID = UUID()
    private let childSessionID = UUID()
    private let siblingSessionID = UUID()

    private var sessionControlOperations: [DomainAgentSessionTargetOperation] {
        DomainAgentSessionTargetOperation.allCases.filter { $0.family == .sessionControl }
    }

    private var monitorOperations: [DomainAgentSessionTargetOperation] {
        DomainAgentSessionTargetOperation.allCases.filter { $0.family == .monitor }
    }

    private var targetBearingMonitorOperations: [DomainAgentSessionTargetOperation] {
        monitorOperations.filter { !$0.isObserverScoped }
    }

    private func monitorProof(
        capability: DomainAgentSessionLinkCapability,
        observerSessionID: UUID? = nil,
        targetSessionID: UUID? = nil
    ) -> DomainAgentSessionMonitorGrantProof {
        DomainAgentSessionMonitorGrantProof(
            linkID: UUID(),
            generation: 7,
            capability: capability,
            observerSessionID: observerSessionID ?? callerSessionID,
            targetSessionID: targetSessionID ?? siblingSessionID
        )
    }

    // MARK: - Control operations

    func testAdministrativePrincipalRetainsRoutedControlForEveryTargetOperation() {
        for operation in sessionControlOperations {
            let decision = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .administrativePrincipal,
                target: .known(targetSessionID: siblingSessionID, parentSessionID: nil)
            )
            XCTAssertEqual(decision.basis, .administrativePrincipal, "\(operation.rawValue)")
        }
    }

    func testAgentCallerMayControlOnlyItsDirectChildren() {
        for operation in sessionControlOperations where operation != .manageCleanup {
            let child = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: childSessionID, parentSessionID: callerSessionID)
            )
            XCTAssertEqual(
                child.basis,
                .directSpawnProvenance(parentSessionID: callerSessionID),
                "\(operation.rawValue)"
            )

            let sibling = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: siblingSessionID, parentSessionID: UUID())
            )
            XCTAssertEqual(sibling.denial, .notDirectChild, "\(operation.rawValue)")

            let orphan = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: siblingSessionID, parentSessionID: nil)
            )
            XCTAssertEqual(
                orphan.denial,
                .notDirectChild,
                "an unparented top-level session is never controllable by an agent: \(operation.rawValue)"
            )
        }
    }

    func testAgentCannotDeleteSavedSessionsEvenWithDirectSpawnProvenance() {
        let targets: [DomainAgentSessionTargetProvenance] = [
            .known(targetSessionID: childSessionID, parentSessionID: callerSessionID),
            .known(targetSessionID: siblingSessionID, parentSessionID: nil),
            .unknown(targetSessionID: siblingSessionID)
        ]
        for target in targets {
            let decision = DomainAgentSessionOperationAuthorizer.authorize(
                operation: .manageCleanup, caller: .agentSession(callerSessionID), target: target,
                monitorGrant: monitorProof(capability: .sendWhenIdle)
            )
            XCTAssertEqual(decision.denial, .humanOnlyOperation)
        }
    }

    func testGrandchildIsNotDirectlyControllable() {
        let grandchildParent = childSessionID
        let decision = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .runSteer,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: UUID(), parentSessionID: grandchildParent)
        )
        XCTAssertEqual(decision.denial, .notDirectChild, "authority is direct, not transitive")
    }

    func testUnknownTargetProvenanceAndUnresolvedRoutingFailClosed() {
        for operation in sessionControlOperations {
            let unknownTarget = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .unknown(targetSessionID: siblingSessionID)
            )
            XCTAssertEqual(unknownTarget.denial, operation == .manageCleanup ? .humanOnlyOperation : .targetProvenanceUnknown, "\(operation.rawValue)")

            let unresolvedCaller = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .unresolvedAgentRun,
                target: .known(targetSessionID: childSessionID, parentSessionID: callerSessionID)
            )
            XCTAssertEqual(unresolvedCaller.denial, .callerRoutingUnresolved, "\(operation.rawValue)")
        }
    }

    func testAgentCallerCannotTargetItsOwnSession() {
        let decision = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .runRespond,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: callerSessionID, parentSessionID: nil)
        )
        XCTAssertEqual(
            decision.denial,
            .selfTarget,
            "self-targeting would let an agent answer its own pending interaction"
        )
    }

    func testMonitorGrantNeverAuthorizesAnExistingControlOperation() {
        for operation in sessionControlOperations {
            let decision = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: siblingSessionID, parentSessionID: UUID()),
                monitorGrant: monitorProof(capability: .sendWhenIdle)
            )
            XCTAssertEqual(
                decision.denial,
                operation == .manageCleanup ? .humanOnlyOperation : .notDirectChild,
                "an oversight link must not widen agent_run/agent_manage: \(operation.rawValue)"
            )
        }
    }

    // MARK: - Monitor operations

    func testMonitorOperationsRequireTheExactGrantCapability() {
        let expected: [DomainAgentSessionTargetOperation: DomainAgentSessionLinkCapability] = [
            .monitorPoll: .poll,
            .monitorWait: .wait,
            .monitorRead: .read,
            .monitorSend: .sendWhenIdle,
            .monitorCompact: .sendWhenIdle,
            // Observer-local admission policy, so it needs the read grant it already holds over the
            // lane and nothing stronger.
            .monitorSnoozeAutoWake: .poll,
            // Acting for the user in the target needs the user's explicit management delegation.
            .monitorRespond: .manage,
            .monitorSteer: .manage,
            .monitorStop: .manage,
            .monitorSetModel: .manage,
            .monitorRetireLane: .manage,
            // Redirecting another session's execution checkout acts for the user in that target.
            .monitorWorktreeBinding: .manage
        ]
        for operation in targetBearingMonitorOperations {
            guard let capability = expected[operation] else {
                XCTFail("missing expectation for \(operation.rawValue)")
                continue
            }
            XCTAssertEqual(operation.requiredMonitorCapability, capability, "\(operation.rawValue)")

            let proof = monitorProof(capability: capability)
            let matching = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
                monitorGrant: proof
            )
            XCTAssertEqual(
                matching.basis,
                .monitorGrant(linkID: proof.linkID, generation: proof.generation, capability: capability),
                "\(operation.rawValue)"
            )

            let wrongCapability: DomainAgentSessionLinkCapability = capability == .read ? .poll : .read
            let mismatched = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
                monitorGrant: monitorProof(capability: wrongCapability)
            )
            XCTAssertEqual(mismatched.denial, .monitorCapabilityMismatch, "\(operation.rawValue)")
        }
    }

    func testMonitorOperationsRejectMissingMismatchedAndNonAgentCallers() {
        let missing = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .monitorRead,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: siblingSessionID, parentSessionID: nil)
        )
        XCTAssertEqual(missing.denial, .missingMonitorGrant)

        let wrongObserver = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .monitorRead,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
            monitorGrant: monitorProof(capability: .read, observerSessionID: UUID())
        )
        XCTAssertEqual(wrongObserver.denial, .monitorGrantObserverMismatch)

        let wrongTarget = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .monitorRead,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
            monitorGrant: monitorProof(capability: .read, targetSessionID: UUID())
        )
        XCTAssertEqual(wrongTarget.denial, .monitorGrantTargetMismatch)

        let administrative = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .monitorRead,
            caller: .administrativePrincipal,
            target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
            monitorGrant: monitorProof(capability: .read)
        )
        XCTAssertEqual(administrative.denial, .monitorRequiresAgentCaller)
    }

    func testSpawnProvenanceDoesNotSilentlyCreateAMonitorGrant() {
        for operation in targetBearingMonitorOperations {
            let decision = DomainAgentSessionOperationAuthorizer.authorize(
                operation: operation,
                caller: .agentSession(callerSessionID),
                target: .known(targetSessionID: childSessionID, parentSessionID: callerSessionID)
            )
            XCTAssertEqual(decision.denial, .missingMonitorGrant, "\(operation.rawValue)")
        }
    }

    // MARK: - Observer-scoped `list`

    func testTargetlessListIsObserverScopedAndCarriesNoCapabilityProof() {
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorList.isObserverScoped)
        XCTAssertNil(
            DomainAgentSessionTargetOperation.monitorList.requiredMonitorCapability,
            "a targetless operation must not demand an arbitrary target's capability"
        )
        for operation in DomainAgentSessionTargetOperation.allCases
            where operation != .monitorList && operation != .monitorCreateLane
        {
            XCTAssertFalse(operation.isObserverScoped, "\(operation.rawValue)")
        }
    }

    func testListCannotBeAuthorizedThroughTheTargetBearingPath() {
        // Routing `list` through the target path would either invent a target or authorize the wrong
        // one, so the matrix refuses it outright.
        let decision = DomainAgentSessionOperationAuthorizer.authorize(
            operation: .monitorList,
            caller: .agentSession(callerSessionID),
            target: .known(targetSessionID: siblingSessionID, parentSessionID: nil),
            monitorGrant: monitorProof(capability: .poll)
        )
        XCTAssertEqual(decision.denial, .observerScopedOperation)
    }

    func testObserverScopedAuthorizationRequiresAnAgentCallerWithAnOutboundLink() {
        let granted = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorList,
            caller: .agentSession(callerSessionID),
            hasActiveOutboundLink: true
        )
        XCTAssertEqual(granted.basis, .observerGrantSet)

        let noLinks = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorList,
            caller: .agentSession(callerSessionID),
            hasActiveOutboundLink: false
        )
        XCTAssertEqual(
            noLinks.denial,
            .noActiveOutboundLink,
            "`list` exists only while at least one outbound link remains"
        )

        let administrative = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorList,
            caller: .administrativePrincipal,
            hasActiveOutboundLink: true
        )
        XCTAssertEqual(administrative.denial, .monitorRequiresAgentCaller)

        let unresolved = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
            operation: .monitorList,
            caller: .unresolvedAgentRun,
            hasActiveOutboundLink: true
        )
        XCTAssertEqual(unresolved.denial, .monitorRequiresAgentCaller)
    }

    func testTargetBearingOperationsCannotUseTheObserverScopedPath() {
        for operation in DomainAgentSessionTargetOperation.allCases where !operation.isObserverScoped {
            let decision = DomainAgentSessionOperationAuthorizer.authorizeObserverScoped(
                operation: operation,
                caller: .agentSession(callerSessionID),
                hasActiveOutboundLink: true
            )
            XCTAssertEqual(decision.denial, .targetScopedOperation, "\(operation.rawValue)")
        }
    }

    // MARK: - Discovery scope

    func testDiscoveryScopeIsDirectChildOnlyForAgentCallers() {
        XCTAssertEqual(
            DomainAgentSessionOperationAuthorizer.discoveryScope(for: .administrativePrincipal),
            .unrestricted
        )
        XCTAssertEqual(
            DomainAgentSessionOperationAuthorizer.discoveryScope(for: .agentSession(callerSessionID)),
            .directChildren(of: callerSessionID)
        )
        XCTAssertEqual(
            DomainAgentSessionOperationAuthorizer.discoveryScope(for: .unresolvedAgentRun),
            .none
        )
    }

    // MARK: - Operation classification

    func testOperationFamiliesAndMutationClassificationAreExhaustive() {
        XCTAssertEqual(
            Set(sessionControlOperations.map(\.rawValue)),
            [
                "agent_run.poll", "agent_run.wait", "agent_run.cancel", "agent_run.steer", "agent_run.respond",
                "agent_manage.list_sessions", "agent_manage.get_log", "agent_manage.extract_handoff",
                "agent_manage.resume_session", "agent_manage.stop_session", "agent_manage.cleanup_sessions"
            ]
        )
        XCTAssertEqual(
            Set(monitorOperations.map(\.rawValue)),
            [
                "agent_session_link.list", "agent_session_link.poll", "agent_session_link.wait",
                "agent_session_link.read", "agent_session_link.send",
                "agent_session_link.create_lane", "agent_session_link.retire_lane",
                "agent_session_link.snooze_auto_wake", "agent_session_link.compact",
                "agent_session_link.respond",
"agent_session_link.steer", "agent_session_link.stop", "agent_session_link.set_model",
                "manage_worktree.binding"
            ]
        )
        for operation in sessionControlOperations where operation.requiredMonitorCapability != nil {
            XCTFail("control operations must never carry an oversight capability: \(operation.rawValue)")
        }
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorCompact.mutatesTarget)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorCompact.isObserverScoped)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorCompact.requiredMonitorCapability, .sendWhenIdle)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorCompact.family, .monitor)
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorSend.mutatesTarget)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorRead.mutatesTarget)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorPoll.isObserverScoped)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorPoll.mutatesTarget)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorPoll.requiredMonitorCapability, .poll)
        XCTAssertTrue(DomainAgentSessionTargetOperation.manageCleanup.mutatesTarget)
        // Snooze names a target because the policy is per-lane, but it never reaches that target: it
        // must stay a non-observer-scoped, non-mutating `.poll` operation, or it would either be
        // authorized against the wrong thing or claim an authority it does not use.
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorSnoozeAutoWake.isObserverScoped)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorSnoozeAutoWake.mutatesTarget)
        XCTAssertEqual(
            DomainAgentSessionTargetOperation.monitorSnoozeAutoWake.requiredMonitorCapability,
            .poll
        )
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorSnoozeAutoWake.family, .monitor)
        // Management: answering and steering mutate, and neither is observer-scoped.
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorRespond.mutatesTarget)
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorSteer.mutatesTarget)
        for operation in [
            DomainAgentSessionTargetOperation.monitorRespond, .monitorSteer
        ] {
            XCTAssertFalse(operation.isObserverScoped, operation.rawValue)
            XCTAssertEqual(operation.requiredMonitorCapability, .manage, operation.rawValue)
        }
        // A watch grant never implies management, and management is never part of version 1.
        XCTAssertFalse(DomainAgentSessionLinkCapability.version1.contains(.manage))
        XCTAssertEqual(
            DomainAgentSessionLinkCapability.managed,
            DomainAgentSessionLinkCapability.version1.union([.manage])
        )
        // Managed Stop mutates one exact target under the Manage grant.
        XCTAssertTrue(DomainAgentSessionTargetOperation.monitorStop.mutatesTarget)
        XCTAssertFalse(DomainAgentSessionTargetOperation.monitorStop.isObserverScoped)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorStop.requiredMonitorCapability, .manage)
        XCTAssertEqual(DomainAgentSessionTargetOperation.monitorStop.family, .monitor)
    }
}

import Foundation
import RepoPromptDomainRuntime
import RepoPromptSettingsCore
@_spi(TestSupport) @testable import RepoPromptApp
import XCTest

final class GrokBuildPermissionAndIdentityTests: XCTestCase {
    // MARK: - Permission option policy

    func testEnableAlwaysApproveIsNeverAutoSelectableForGrok() {
        XCTAssertFalse(
            ACPPermissionOptionPolicy.isAutoSelectable(optionID: "enable-always-approve", for: .grokBuild)
        )
        XCTAssertTrue(ACPPermissionOptionPolicy.isAutoSelectable(optionID: "allow-once", for: .grokBuild))
        XCTAssertTrue(ACPPermissionOptionPolicy.isAutoSelectable(optionID: "allow-edits-session", for: .grokBuild))
    }

    func testOtherProvidersHaveNoDenylistedOptions() {
        XCTAssertTrue(ACPPermissionOptionPolicy.isAutoSelectable(optionID: "enable-always-approve", for: .cursor))
        XCTAssertTrue(ACPPermissionOptionPolicy.isAutoSelectable(optionID: "anything", for: .openCode))
    }

    func testDenylistMatchingNormalizesCaseAndWhitespace() {
        XCTAssertFalse(
            ACPPermissionOptionPolicy.isAutoSelectable(optionID: "  Enable-Always-Approve ", for: .grokBuild)
        )
    }

    // MARK: - MCP client identity

    func testGrokShellFamilyMatchesLiveObservedClientName() {
        // Frozen fixture: captured from grok 1.0.3 connecting to an ACP-injected MCP server
        // named "RepoPromptCE" on 2026-08-13.
        XCTAssertEqual(MCPClientIdentity.canonicalFamilyID("grok-shell-RepoPromptCE"), "grok-shell")
        XCTAssertTrue(MCPClientIdentity.matches("grok-shell-RepoPromptCE", AgentProviderKind.grokBuild.mcpClientNameHint))
    }

    func testRuntimeClientHintAndToolTitlesUseIsolatedServerName() {
        XCTAssertEqual(AgentProviderKind.grokBuild.mcpClientNameHint, "grok-shell-RepoPromptCEGrokRuntime")
        XCTAssertEqual(RepoPromptMCPServerConfiguration.repoPrompt.name, "RepoPromptCE", "Other providers keep the shared name")
        for tool in ["read_file", "ask_user"] {
            let qualified = "RepoPromptCEGrokRuntime__\(tool)"
            XCTAssertEqual(MCPIntegrationHelper.canonicalRepoPromptToolName(qualified), tool)
            XCTAssertEqual(
                ACPRuntimeEventParsing.normalizedToolName(from: ["title": qualified]),
                "mcp__RepoPromptCE__\(tool)"
            )
            XCTAssertEqual(
                MCPIntegrationHelper.repoPromptPermissionAutoApprovalMatch(requestToolName: qualified, requestPayload: [:])?.normalizedToolName,
                tool
            )
            XCTAssertFalse(MCPIntegrationHelper.isRepoPromptToolNameWithServerPrefix("RepoPromptCEGrokRuntimeOther__\(tool)"))
        }
    }

    func testPublicCatalogToolsHaveCanonicalRecognition() {
        var prefixes: [(value: String, explicit: Bool)] = [
            ("", false),
            ("functions.functions.", false)
        ]
        for server in [
            RepoPromptMCPServerConfiguration.defaultServerName,
            RepoPromptMCPServerConfiguration.grokBuildRuntimeServerName
        ] {
            prefixes += [
                ("mcp__\(server)__", true),
                ("mcp_\(server)__", true),
                ("\(server)__", true),
                ("\(server)_", true),
                ("functions.functions.mcp__\(server)__", true)
            ]
        }

        // The public catalog is the oracle: new tools must not silently lose their identity.
        for tool in MCPDomainToolCatalog.orderedToolNames + ["ask_user_question"] {
            let canonical = tool == "ask_user_question" ? "ask_user" : tool
            for prefix in prefixes {
                let name = prefix.value + tool
                XCTAssertEqual(MCPIntegrationHelper.canonicalRepoPromptToolName(name), canonical, name)
                XCTAssertEqual(MCPIntegrationHelper.isRepoPromptToolNameWithServerPrefix(name), prefix.explicit, name)
            }
        }

        for name in [
            "agent_self",
            "mcp__RepoPromptCE__agent_self",
            "functions.functions.RepoPromptCEGrokRuntime__agent_self",
            "not_a_public_tool",
            "RepoPromptCE__not_a_public_tool",
            "mcp__OtherServer__manage_worktree",
            "RepoPromptCEGrokRuntimeOther__self_compact"
        ] {
            XCTAssertNil(MCPIntegrationHelper.canonicalRepoPromptToolName(name), name)
            XCTAssertFalse(MCPIntegrationHelper.isRepoPromptToolNameWithServerPrefix(name), name)
        }
    }

    func testGrokShellFamilyRequiresSeparatorBoundary() {
        XCTAssertNil(MCPClientIdentity.canonicalFamilyID("grok-shellx"))
        XCTAssertNil(MCPClientIdentity.canonicalFamilyID("grok-shel"))
        XCTAssertEqual(MCPClientIdentity.canonicalFamilyID("grok-shell"), "grok-shell")
    }

    // MARK: - Controller reuse key

    func testGrokControllerReuseKeysOnPermissionAndModel() async throws {
        let workspace = try makeTestDirectory(name: "GrokBuildReuseKeyTests")
        func makeController(autoApprove: Bool, model: String?) throws -> ACPAgentSessionController {
            try ACPAgentSessionController(
                provider: ReuseKeyFakeGrokProvider(),
                runRequest: ACPRunRequest(
                    agentKind: .grokBuild,
                    modelString: model,
                    workspacePath: workspace.path,
                    resumeSessionID: nil,
                    attachments: [],
                    taskLabelKind: nil,
                    autoApproveAllToolPermissions: autoApprove
                )
            )
        }
        func request(autoApprove: Bool, model: String?) -> ACPRunRequest {
            ACPRunRequest(
                agentKind: .grokBuild,
                modelString: model,
                workspacePath: workspace.path,
                resumeSessionID: nil,
                attachments: [],
                taskLabelKind: nil,
                autoApproveAllToolPermissions: autoApprove
            )
        }

        let managed = try makeController(autoApprove: false, model: nil)
        let managedCompatible = await managed.isCompatibleWith(request: request(autoApprove: false, model: nil))
        let managedPermissionMismatch = await managed.isCompatibleWith(request: request(autoApprove: true, model: nil))
        let managedModelMismatch = await managed.isCompatibleWith(request: request(autoApprove: false, model: "grok-4.5"))
        XCTAssertTrue(managedCompatible)
        XCTAssertFalse(managedPermissionMismatch, "permission change must force a fresh Grok process")
        XCTAssertFalse(managedModelMismatch, "concrete→default/model change must force a fresh Grok process")

        let explicit = try makeController(autoApprove: false, model: "grok-4.5")
        let explicitSame = await explicit.isCompatibleWith(request: request(autoApprove: false, model: "grok-4.5"))
        let explicitCaseVariant = await explicit.isCompatibleWith(request: request(autoApprove: false, model: "GROK-4.5"))
        XCTAssertTrue(explicitSame)
        XCTAssertTrue(explicitCaseVariant, "normalized model raw comparison is case-insensitive")

        await managed.shutdown()
        await explicit.shutdown()
    }
}

/// Minimal Grok provider double for controller-lifecycle tests (no launch resolution).
private struct ReuseKeyFakeGrokProvider: ACPAgentProvider {
    var providerID: ACPProviderID {
        .grokBuild
    }

    func support(for _: ACPRunRequest) async -> ACPSupportResult {
        .supported
    }

    func makeLaunchConfiguration(for request: ACPRunRequest) throws -> ACPLaunchConfiguration {
        ACPLaunchConfiguration(
            providerID: providerID,
            command: "/bin/echo",
            arguments: [],
            environment: [:],
            workingDirectory: request.workspacePath,
            additionalPathHints: [],
            enableDebugLogging: false
        )
    }

    func makeSessionConfiguration(
        for request: ACPRunRequest,
        mcpServer _: RepoPromptMCPServerConfiguration
    ) throws -> ACPSessionConfiguration {
        try ACPSessionConfiguration(
            mode: .new,
